import { openHiddenTab } from "./focus";
function createHiddenSession() {
  return { host: { createTab: vi.fn(), focus: vi.fn(), release: vi.fn() } };
}
test("closing a hidden session releases control", () => {
  const { host } = createHiddenSession();
  host.release();
  expect(host.release).toHaveBeenCalled();
});
